class ta_matchers(object):
    @staticmethod
    def assert_matches(actual, expected):
        """Raise MatchingError if the actual value does not match the expected one."""
        expected.match(actual)

    @staticmethod
    def is_matching(actual, expected):
        """Return True if the actual value matches the expected one, and False otherwise."""
        return expected.matches(actual)
